import pandas as pd

def solve(data):
     df = pd.DataFrame(data['rows'], columns=['qty','price'])
     df['revenue'] = df['qty'] * df['price']
     df.loc[df['qty'] >= 3, 'revenue'] = data['cap']
     return df['revenue'].tolist()
